={
  "model": "sonar",
  "messages": [
    {
      "role": "system",
      "content": "You are an expert ecommerce deal and coupon researcher.
Your task is to search across major coupon sites (such as RetailMeNot, CouponCabin, Slickdeals, Dealspotr, Honey) and official merchant sites to find current, active, verified promo codes, coupon codes, and discount deals for the requested store.

RULES:
1. Extract REAL coupon codes if available (e.g. SAVE20, WELCOME10, FREESHIP).
2. Distinguish between 'voucher' (has promo code) and 'deal' (no code needed, sale/clearance).
3. For discountText, use short punchy labels: e.g. '20% OFF', '$15 OFF', 'FREE SHIPPING', 'UP TO 50% OFF'.
4. Exclude expired, invalid, or fake deals.
5. Provide a clear shopper-friendly title and 1-2 sentence description explaining any exclusions.

Return ONLY a valid JSON object matching this schema:
{
  "deals": [
    {
      "title": "20% Off Storewide",
      "code": "CODE20",
      "type": "voucher",
      "discountText": "20% OFF",
      "description": "Save 20% on all orders. Exclusions may apply.",
      "terms": "Valid online only.",
      "sourceName": "RetailMeNot",
      "endDate": null
    }
  ]
}"
    },
    {
      "role": "user",
      "content": "Find all active promo codes, coupon vouchers, and discounts for '" + ($json.body.storeName || $json.body.advertiserName || "Store") + "' " + ($json.body.domain ? "(website: " + $json.body.domain + ")" : "") + " across popular coupon sites like RetailMeNot, CouponCabin, and the merchant site."
    }
  ],
  "max_tokens": 1500,
  "temperature": 0.1
}

parameters.jsCode:
// Extract data from webhook and Perplexity AI response
const inputData = $('Webhook Trigger').first().json.body || {};
const advertiserId = inputData.advertiserId ? Number(inputData.advertiserId) : undefined;
const storeName = inputData.storeName || inputData.advertiserName || "Merchant";
const network = inputData.network || "awin";
const domain = inputData.domain || "";

const rawContent = $json.choices?.[0]?.message?.content || "{}";

// Extract JSON object safely
let parsed = { deals: [] };
try {
  const fence = rawContent.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const cleanText = fence ? fence[1].trim() : rawContent.trim();
  const start = cleanText.indexOf('{');
  const end = cleanText.lastIndexOf('}');
  if (start !== -1 && end !== -1) {
    parsed = JSON.parse(cleanText.slice(start, end + 1));
  }
} catch (e) {
  parsed = { deals: [] };
}

const rawDeals = Array.isArray(parsed.deals) ? parsed.deals : [];
const seenCodes = new Set();
const cleanedDeals = [];

for (const d of rawDeals) {
  const code = d.code ? String(d.code).trim().toUpperCase() : null;
  if (code) {
    if (seenCodes.has(code)) continue;
    seenCodes.add(code);
  }

  cleanedDeals.push({
    advertiserId,
    advertiserName: storeName,
    network,
    title: (d.title || `Offer at ${storeName}`).trim(),
    description: d.description ? String(d.description).trim() : null,
    code: code || undefined,
    type: code ? "voucher" : (d.type || "deal"),
    discountText: d.discountText ? String(d.discountText).trim() : null,
    terms: d.terms ? String(d.terms).trim() : null,
    sourceName: d.sourceName || "Web Research",
    endDate: d.endDate || null,
    confidenceScore: 0.95
  });
}

return {
  json: {
    advertiserId,
    storeName,
    network,
    domain,
    foundCount: cleanedDeals.length,
    deals: cleanedDeals
  }
};
